 setEditorTheme(val || "p5-learn");
 });
 AsyncStorage.getItem("setting_codeFontSize").then((val) => {
 setCodeFontSize(val ? parseInt(val, 10) : DEFAULTS.codeFontSize);
 });
  AsyncStorage.getItem("setting_keyboardHeight").then((val) => {
