const fs=require('fs'),path=require('path'),y=require('js-yaml');
const files=fs.readdirSync('src/data/courses').filter(f=>f.endsWith('.yaml'));
let checked=0,unchecked=[];
for(const f of files){
  const c=y.load(fs.readFileSync(path.join('src/data/courses',f),'utf8'));
  for(const ex of c.exercises||[]){
    const tasks=ex.tasks||[];
    tasks.forEach((t,i)=>{
      const isFinal=i===tasks.length-1;
      const hasSol=t.solution || (isFinal && ex.solution);
      if(hasSol) checked++; else unchecked.push({course:ex.slug,ex:ex.id,task:t.id,rules:(t.validation||[]).map(r=>r.type+':'+r.name).join(',')});
    });
  }
}
console.log('tasks whose rules are checked against a solution by check-exercises:', checked);
console.log('tasks NEVER checked by check-exercises:', unchecked.length);
for(const u of unchecked) console.log('  ', JSON.stringify(u));
"

