const fs=require('fs'),path=require('path'),y=require('js-yaml');
const files=fs.readdirSync('src/data/courses').filter(f=>f.endsWith('.yaml'));
let onlyCall=0, withPixel=0;
const byCourse={};
for(const f of files){
  const c=y.load(fs.readFileSync(path.join('src/data/courses',f),'utf8'));
  for(const ex of c.exercises||[]){
    for(const t of ex.tasks||[]){
      const types=(t.validation||[]).map(r=>r.type);
      if(types.includes('pixelMatch')||types.includes('expectedPixels')) withPixel++; else { onlyCall++; byCourse[c.slug]=(byCourse[c.slug]||0)+1; }
    }
  }
}
console.log('tasks with pixel validation:', withPixel);
console.log('tasks validated ONLY by functionCall/functionExists (fakeable):', onlyCall);
console.log(byCourse);
"

