const { parser } = require('@lezer/javascript');
const src = 'function circle(a,b,c){}\nconst f = (x) => x+1;\nlet v = createVector(1,2,3);\nv.add(5);\ncircle(1,2,3);\nimg.get(1,1);\nfunction setup(){createCanvas(400,400);}';
const tree = parser.parse(src);
function walk(node, depth){
  let out='';
  const c = node.firstChild;
  let n = c;
  while(n){ out += ' '.repeat(depth) + n.name + ' ['+n.from+','+n.to+'] ' + JSON.stringify(src.slice(n.from,n.to)).slice(0,50) + '\n' + walk(n, depth+2); n=n.nextSibling; }
  return out;
}
console.log(walk(tree.topNode,0));
" 2>&1 | head -80

