import { parser } from "@lezer/javascript";
function walk(cursor, depth, cb){
  if (depth > 200) return;
  cb(cursor, depth);
  if (cursor.firstChild()){
    do { walk(cursor, depth+1, cb); } while (cursor.nextSibling());
    cursor.parent();
  }
}
function argCount(src){
  const out=[];
  const tree = parser.parse(src);
  const cur = tree.cursor();
  walk(cur, 0, (c, d) => {
    if (c.type.name === 'CallExpression' || c.type.name === 'NewExpression') {
      let args = 0;
      if (c.firstChild()) {
        do {
          if (c.type.name === 'ArgList') {
            let exprs = 0;
            if (c.firstChild()) {
              do {
                const n = c.type.name;
                if (n !== '(' && n !== ')' && n !== ',') exprs++;
              } while (c.nextSibling());
              c.parent();
            }
            args = exprs;
          }
        } while (c.nextSibling());
        c.parent();
      }
      out.push(JSON.stringify(src.slice(c.from, c.to)) + ' args=' + args);
    }
  });
  return out;
}
const cases = [
  'f(1,2,3)', 'f()', 'f((1,2))', 'f(a, b + c, g(1,2))', 'f(`a,${x},c`)',
  'f(...args)', 'f(1,2,)', 'f(x = 1, 2)', 'new p5(undefined, el)',
  'circle ( 1, 2 , 3 )', 'f(\n1,\n2\n)',
];
for (const s of cases) console.log(JSON.stringify(s), '=>', argCount(s).join(' | '));
EOF
