export function evaluateRules(analysis, rules): { passed: boolean; reason: string; skippedPixelRules: boolean } {
  for (const rule of rules) {
    switch (rule.type) {
      case "functionCall": {
        const matches = analysis.calls.filter(c => c.name === rule.name);
        if (matches.length === 0) return { passed:false, reason:`Add a ${rule.name}() call`, skippedPixelRules:false };
        if (typeof rule.exactArgs === "number") {
          if (!matches.some(c => c.args === rule.exactArgs)) return { passed:false, reason:`${rule.name}() needs ${rule.exactArgs} arguments`, skippedPixelRules:false };
        }
        if (typeof rule.minArgs === "number") {
          if (!matches.some(c => c.args >= rule.minArgs)) return { passed:false, reason:`${rule.name}() needs at least ${rule.minArgs} arguments`, skippedPixelRules:false };
        }
        break;
      }
      case "functionExists": {
        if (!analysis.functionDefs.has(rule.name)) return { passed:false, reason:`Define a ${rule.name}() function`, skippedPixelRules:false };
        break;
      }
      case "canvasSize": {
        if (!analysis.canvasPresent) return { passed:false, reason:"Use createCanvas() to set canvas size", skippedPixelRules:false };
        if (!analysis.canvas || analysis.canvas.width !== rule.width || analysis.canvas.height !== rule.height) {
