  var touchStartX = 0;
  var isScrolling = false;
  view.dom.addEventListener('touchstart', function(e) {
    var touch = e.touches[0];
    touchStartX = touch.clientX;
    touchStartY = touch.clientY;
    isScrolling = false;
  }, { passive: true });
