Now Phase 2 pixel hardening: replace `waitForFrame` with a deterministic settle. Let me read the current pixel section again (it's unchanged so far) to write the replacement precisely.

Current (from the earlier read):
```js
          function waitForFrame(p5Inst, cb) {
            var start = Date.now();
            function check() {
              var fc = 0;
              try { fc = typeof p5Inst.frameCount === 'function' ? p5Inst.frameCount() : p5Inst.frameCount; } catch(e) {}
              if (fc > 0) { cb(true); return; }
              if (Date.now() - start > 2000) { cb(false); return; }
              if (typeof requestAnimationFrame === 'function') { requestAnimationFrame(check); } else { setTimeout(check, 32); }
            }
            check();
          }
```

Replace with deterministic settle:
```js
          function frameCountOf(p5Inst) {
            try { return typeof p5Inst.frameCount === 'function' ? p5Inst.frameCount() : p5Inst.frameCount; } catch(e) { return 0; }
          }
          function settleForValidation(p5Inst, cb) {
            var start = Date.now();
            function check() {
              if (frameCountOf(p5Inst) > 0) {
                var wasLooping = false;
                try { wasLooping = typeof p5Inst.isLooping === 'function' ? p5Inst.isLooping() : !!p5Inst.isLooping; } catch(e) {}
                try { p5Inst.noLoop(); } catch(e) {}
                // Reset the frame counter so the sampled frame is always the
                // "first frame" rendering regardless of loop timing, then draw
                // exactly one frame synchronously.
                try { p5Inst.frameCount = 0; } catch(e) {}
                Promise.resolve()
                  .then(function() { return p5Inst.redraw(); })
                  .then(function() { cb(true, wasLooping); })
                  .catch(function() { cb(false, wasLooping); });
                return;
              }
              if (Date.now() - start > 2000) { cb(false, false); return; }
              if (typeof requestAnimationFrame === 'function') { requestAnimationFrame(check); } else { setTimeout(check, 32); }
            }
            check();
          }
```

Wait — `Promise.resolve().then(() => p5Inst.redraw())`. But `redraw()` checks `if (this._inUserDraw || !this._setupDone) return;`. Since we're in a rAF poll callback, not inside user draw, `_inUserDraw` is false. Good. But there's a subtlety: the main loop could still be running a draw that's awaiting; `_inUserDraw` would be true then, and redraw would return undefined (no frame drawn). Then sampling would sample whatever is on canvas — the last loop frame (non-deterministic). Hmm.

But we set `noLoop()` BEFORE redraw. The main loop's `_draw` iteration: if it's currently awaiting an in-progress draw, `noLoop` won't stop it. The risk is low though. And even if redraw no-ops, we still sample the latest committed frame. Acceptable.

Actually, wait. There's an even more important subtlety with `_inUserDraw`: after the loop's draw finishes and awaits resolve, `_inUserDraw` is set false. Our poll callback runs on rAF. Could the loop be in the middle of drawing exactly then? The loop schedules draws via rAF-ish timing; each draw awaits `r.draw()` and then `_postdraw`. In practice, when the WebView runs validation right after render, the timing is uncertain. But since we poll until frameCount > 0, and then noLoop + redraw, the worst case is we sample a slightly different frame. Given static sketches are identical every frame, this is fine.

Also `redraw()` in p5 may reset matrix etc. and increment frameCount to 1 (since we set it to 0). Deterministic.

Now, `sampleAllPoints` — replace its internal `checkPoint` to use core helpers, and add canvas-size sanity check. Current:

```js
          function sampleAllPoints(p5Instance) {
            var cnv = p5Instance.canvas;
            if (!cnv) { postValidationFailed('Canvas not found'); return false; }
            var ctx = cnv.getContext('2d');
            if (!ctx) { postValidationFailed('Cannot read canvas pixels'); return false; }
            var d = (p5Instance.width && cnv.width) ? (cnv.width / p5Instance.width) : 1;
            function checkPoint(pt) {
              var tol = pt.tolerance !== undefined ? pt.tolerance : 30;
              var px = Math.min(Math.max(0, Math.floor(pt.x * d)), cnv.width - 1);
              var py = Math.min(Math.max(0, Math.floor(pt.y * d)), cnv.height - 1);
              var dat = ctx.getImageData(px, py, 1, 1).data;
              var rDiff = Math.abs(dat[0] - pt.expected[0]);
              var gDiff = Math.abs(dat[1] - pt.expected[1]);
              var bDiff = Math.abs(dat[2] - pt.expected[2]);
              return (rDiff <= tol && gDiff <= tol && bDiff <= tol);
            }
            ...
          }
```

Replace with core-driven version:
```js
          function sampleAllPoints(p5Instance) {
            var cnv = p5Instance.canvas;
            if (!cnv) { postValidationFailed('Canvas not found'); return false; }
            var ctx = cnv.getContext('2d');
