settleForValidation(frameContainer.__p5, function(rendered, wasLooping) {
  if (!rendered) { postValidationFailed('Sketch did not render in time — try again'); return; }
  try {
    var ok = sampleAllPoints(frameContainer.__p5);
    if (wasLooping) {
