   name: string;
   args: number;
   member: boolean;
   from: number;
   to: number;
 }

 export interface Analysis {
   calls: ParsedCall[];
   functionDefs: Set<string>;
   canvas: { width: number; height: number } | null;
   canvasPresent: boolean;
 }

 const FUNCTION_KINDS = new Set(["ArrowFunction", "FunctionExpression"]);
 const ARG_SEPARATORS = new Set(["(", ")", ","]);

